[5219] = { en = "Target: Dalson's Tears", tier = 4,
  t = "Doelwit: Dalson's Tears",
  d = "Een van de plaagketels staat op het veld van een vroegere boerderij die nu Dalson's Tears heet. Nou, vandaag laten wij geen tranen: we houden de Scourge tegen en laten ze stikken in hun eigen dampen!$B$BGa naar Dalson's Tears, bijna recht ten noorden van Andorhal, en schakel de ketelheer daar uit. Hij zou net als de vorige een sleutel moeten hebben, waarmee je in de ketel kunt. Gebruik deze fles om een monster uit de ketel te nemen; elke ketel heeft zijn eigen brouwsel van gifstoffen.",
  o = "Ga naar Dalson's Tears in Western Plaguelands om de Cauldron Lord daar te vinden en te verslaan, en gebruik zijn sleutel om toegang te krijgen tot de ketel. Je moet de Empty Dalson's Tears Bottle bij je hebben om een monster te nemen van het gif in de ketel.",
  p = "Een toegangsluik van de ketel zit nog stevig dicht. Om het te openen, moet je de sleutel vinden.",
  c = "De macabere sleutel van de ketelheer glijdt makkelijk in een sleutelgat en verdwijnt dan, zodat je er voortaan altijd bij kunt. Ruwe, stroperige vloeistoffen pulseren door gedraaide buizen in het onderstel van de ketel.$B$BEr zit een kraantje waar de fles net onder past, zodat je een monster kunt aftappen voor High Priestess MacDonnell in Chillwind Point.",
  g = { {"plaagketels", "plague cauldrons (plaagketel)"}, {"tranen", "tears (traan)"}, {"stikken", "choke"}, {"dampen", "fumes (damp)"}, {"recht ten noorden", "due north"}, {"schakel", "eliminate (uitschakelen)"}, {"gifstoffen", "toxins (gifstof)"}, {"macabere", "macabre (macaber)"}, {"glijdt", "slides (glijden)"}, {"voortaan", "from now on"}, {"stroperige", "viscous, syrupy (stroperig)"}, {"pulseren", "pulsate"}, {"gedraaide", "twisted (gedraaid)"}, {"onderstel", "underpinning, base"} },
},

[5220] = { en = "Return to Chillwind Camp", tier = 4,
  t = "Terug naar Chillwind Camp",
  d = "Je vult de fles voorzichtig met genoeg vloeistof uit de ketel voor wat jij een monster van de juiste grootte vindt.$B$BNu je het gif hebt, is het tijd om terug te gaan naar High Priestess MacDonnell in Chillwind Camp om de missie af te ronden.",
  o = "Breng de Filled Dalson's Tears Bottle naar High Priestess MacDonnell in Chillwind Camp, Western Plaguelands.",
  p = "We weten dat elke ketel een ander mengsel van reagentia gebruikt om zijn plaaggif te maken; we weten ook dat we voor elke ketel een eigen tegengif moeten ontwikkelen. Jouw monster uit Dalson's Tears wordt de sleutel om uit te zoeken welke reagentia die ketel precies nodig heeft.",
  c = "Ah, hier zit genoeg in om te onderzoeken. Goed gedaan, $N!$B$BVoorlopig ligt de volgende stap in onze handen. We moeten een lijst maken van reagentia die, samen met wat al in de ketel zit, als tegengif werken.$B$BDe enige manier om dit erin te krijgen, is door de reagentia rechtstreeks in de ketel te doen. Alchemist Arbington weet daar meer over, dus praat zo snel mogelijk met hem.",
  g = { {"vloeistof", "liquid, fluid"}, {"grootte", "size"}, {"af te ronden", "to complete (afronden)"}, {"reagentia", "reagents"}, {"plaaggif", "plague toxin"}, {"ontwikkelen", "develop"}, {"uit te zoeken", "to figure out (uitzoeken)"}, {"voorlopig", "for now"}, {"rechtstreeks", "directly"}, {"zo snel mogelijk", "as soon as possible"} },
},

