[5222] = { en = "Target: Writhing Haunt", tier = 4,
  t = "Doelwit: Writhing Haunt",
  d = "Twee ketels zijn met succes geopend; je kunt er voortaan altijd bij, maar we willen ook de andere twee nog openen. Dan hebben we allemaal meer mogelijkheden om het tegengif toe te voegen!$B$BDeze keer val je de ketel van de Writhing Haunt aan. Die ligt bijna recht ten oosten van Andorhal, vrij dicht bij de verwoeste stadsmuren; schakel ook nu de ketelheer daar uit voor zijn sleutel. Gebruik deze fles om het monster uit de ketel te nemen.$B$BGoede jacht, $N!",
  o = "Ga naar de Writhing Haunt in Western Plaguelands om de Cauldron Lord daar te vinden en te verslaan, en gebruik zijn sleutel om toegang te krijgen tot de ketel. Je moet de Empty Writhing Haunt Bottle bij je hebben om een monster te nemen van het gif in de ketel.",
  p = "Een toegangsluik van de ketel zit nog stevig dicht. Om het te openen, moet je de sleutel vinden.",
  c = "De sleutel van de ketelheer opent het toegangsluik van deze ketel en verdwijnt dan, net zoals de andere sleutels bij de vorige twee ketels. Onder het platform van de ketel kolkt heftig een stof met een rotte geur.$B$BEr zit een kraantje waar de fles net onder past, zodat je een monster kunt aftappen voor High Priestess MacDonnell in Chillwind Point.",
  g = { {"met succes", "successfully"}, {"voortaan", "from now on, indefinitely"}, {"mogelijkheden", "options (mogelijkheid)"}, {"recht ten oosten", "due east"}, {"verwoeste", "ruined (verwoest)"}, {"stadsmuren", "city walls (stadsmuur)"}, {"schakel", "eliminate (uitschakelen)"}, {"jacht", "hunting"}, {"toegangsluik", "access panel, access hatch"}, {"kolkt", "churns (kolken)"}, {"heftig", "violently"}, {"rotte", "putrid, rotten (rot)"} },
},

[5223] = { en = "Return to Chillwind Camp", tier = 4,
  t = "Terug naar Chillwind Camp",
  d = "Je vult de lege fles voorzichtig tot de rand; een monster van de smerige stof die onder het platform van de ketel kolkt, golft nu heen en weer in het breekbare glazen flesje.$B$BNu je het gif hebt, is het tijd om terug te gaan naar High Priestess MacDonnell in Chillwind Camp om de missie af te ronden.",
  o = "Breng de Filled Writhing Haunt Bottle naar High Priestess MacDonnell in Chillwind Camp, Western Plaguelands.",
  p = "Zodra we het monster uit de ketel van de Writhing Haunt met succes onderzocht hebben, hebben we een derde manier om de Scourge een verwoestend tegengif toe te dienen!",
  c = "Weer een prima uitgevoerde missie, $N! Nu kunnen we drie ketels tegen de Scourge inzetten. Als de necromantische macht van Kel'Thuzad over deze landen niet zo sterk was als nu, zou ik durven zeggen dat jij ze helemaal had uitgeschakeld!$B$BAlchemist Arbington zal een verslag hebben over wat deze ketel - en ook de andere omgebogen ketels - nodig heeft om ons tegengif tegen de plaag af te leveren. En nu is het tijd om de laatste ketel van het westen onder onze invloed te brengen!",
  g = { {"vult", "fill (vullen)"}, {"tot de rand", "to the brim"}, {"smerige", "foul, filthy (smerig)"}, {"kolkt", "churns, swirls (kolken)"}, {"golft", "sloshes, waves (golven)"}, {"breekbare", "fragile (breekbaar)"}, {"met succes", "successfully"}, {"verwoestend", "devastating"}, {"uitgevoerde", "executed (uitvoeren)"}, {"inzetten", "to deploy, use against"}, {"necromantische", "necromantic"}, {"omgebogen", "subverted, turned (ombuigen)"}, {"invloed", "influence"}, {"toe te dienen", "to deliver, administer (toedienen)"} },
},

[5224] = { en = "Writhing Haunt Cauldron", tier = 4,
  t = "De ketel van de Writhing Haunt",
  p = "De plaagketel van de Scourge staat voor je en spuwt enorme hoeveelheden gif in de lucht. In de voet van het enorme platform van de ketel zit een klein, onopvallend toegangsluik.$B$BJe hebt de ketelheer al verslagen en zijn sleutel gekregen, dus je kunt nu de juiste reagentia aan de ketel toevoegen om een tegengif tegen de plaag te maken.",
  c = "Als je de reagentia aan het mengsel in de ketel toevoegt, beginnen de kleur en de structuur van de wolk die eruit komt te veranderen. Scourge die ook maar enigszins in de buurt van de ketel zijn, lijken terug te deinzen nu de nieuwe stoffen in de omgeving komen.",
  g = { {"plaagketel", "plague cauldron"}, {"spuwt", "spews (spuwen)"}, {"hoeveelheden", "amounts (hoeveelheid)"}, {"onopvallend", "inconspicuous, nondescript"}, {"toegangsluik", "access panel, access hatch"}, {"ketelheer", "cauldron lord"}, {"reagentia", "reagents"}, {"tegengif", "counter agent, antidote"}, {"structuur", "texture"}, {"enigszins", "somewhat, remotely"}, {"terug te deinzen", "to recoil (terugdeinzen)"} },
},

[5234] = { en = "Return to the Bulwark", tier = 4,
  t = "Terug naar de Bulwark",
  d = "Je vult de lege fles voorzichtig tot de rand; een monster van de smerige stof die onder het platform van de ketel kolkt, golft nu heen en weer in het breekbare glazen flesje.$B$BNu je het gif hebt, is het tijd om terug te gaan naar Shadow Priestess Vandis bij de Bulwark om de missie af te ronden.",
  o = "Breng de Filled Writhing Haunt Bottle naar Shadow Priestess Vandis bij The Bulwark, Western Plaguelands.",
  p = "Zodra we het monster uit de ketel van de Writhing Haunt met succes onderzocht hebben, hebben we een derde manier om een verwoestend tegengif tegen de Scourge in te zetten!",
  c = "Weer een prima uitgevoerde missie, $N! Nu kunnen we drie ketels tegen de Scourge inzetten. Als de necromantische macht van Kel'Thuzad over deze landen niet zo sterk was als nu, zou ik durven zeggen dat jij ze helemaal had uitgeschakeld!$b$bApothecary Dithers zal een verslag hebben over wat deze ketel - en ook de andere omgebogen ketels - nodig heeft om ons tegengif tegen de plaag af te leveren. En nu is het tijd om de laatste ketel van het westen onder onze invloed te brengen!",
  g = { {"vult", "fill (vullen)"}, {"tot de rand", "to the brim"}, {"smerige", "foul, filthy (smerig)"}, {"kolkt", "churns, swirls (kolken)"}, {"golft", "sloshes, waves (golven)"}, {"breekbare", "fragile (breekbaar)"}, {"met succes", "successfully"}, {"verwoestend", "devastating"}, {"uitgevoerde", "executed (uitvoeren)"}, {"inzetten", "to deploy, use against"}, {"necromantische", "necromantic"}, {"omgebogen", "subverted, turned (ombuigen)"}, {"invloed", "influence"} },
},

[5401] = { en = "Argent Dawn Commission", tier = 4,
  t = "Aanstelling bij de Argent Dawn",
  c = "Iedereen die namens de Argent Dawn tegen het kwaad vecht, moet onze aanstelling dragen. Wie die draagt, verdient het recht op de beloningen die onze kwartiermeesters te bieden hebben.$B$BMet de aanstelling kun je Scourgestones krijgen van verslagen Scourge; dat zijn insignes die ze soms bij zich hebben. Verzamel deze insignes en breng ze naar mij. Voor elke set die je inlevert, krijg je ons teken van heldenmoed - de Argent Dawn Valor Token.$B$BVervul je lot, $c - doe vandaag nog mee aan de strijd!",
  g = { {"aanstelling", "commission, appointment"}, {"namens", "on behalf of"}, {"kwaad", "evil"}, {"beloningen", "rewards (beloning)"}, {"kwartiermeesters", "quartermasters (kwartiermeester)"}, {"verslagen", "slain, defeated (verslaan)"}, {"insignes", "insignia (insigne)"}, {"inlevert", "turn in (inleveren)"}, {"heldenmoed", "heroism"}, {"vervul", "fulfil (vervullen)"}, {"lot", "destiny, fate"} },
},

[5404] = { en = "Corruptor's Scourgestones", tier = 4,
  t = "Corruptor's Scourgestones",
  p = "Een Corruptor's Scourgestone is het insigne van de opperheren van de Scourge. Een machtig wezen met gezag over de Scourge heeft er altijd een bij zich. Zo'n kwaadaardig wezen doden zou de zaak van de Argent Dawn zeker vooruithelpen - en alle goede zaken!$B$BNamens de Argent Dawn geef ik je een erepenning in ruil voor maar één van deze insignes. Wees voorzichtig als je er een probeert te krijgen, $N - met zulke machtige wezens valt niet te spotten.",
  c = "Gefeliciteerd, $N - ik ben blij je een erepenning van de Argent Dawn te geven!$B$BAls je op deze manier een erepenning krijgt, laat dat zien dat je een echte held bent voor de goede zaak. We waarderen alle inzet tegen de Scourge, maar een van hun leiders verslaan betekent hun echt een verpletterende nederlaag toebrengen!$B$BVoor de Dawn, mijn $gbroeder:zuster;!",
  g = { {"insigne", "insignia"}, {"opperheren", "overlords (opperheer)"}, {"gezag", "authority"}, {"kwaadaardig", "malevolent, evil"}, {"vooruithelpen", "advance, help forward"}, {"erepenning", "valor token, medal of honour"}, {"in ruil voor", "in exchange for"}, {"valt niet te spotten", "are not to be trifled with"}, {"inzet", "effort"}, {"verpletterende", "crushing (verpletterend)"}, {"nederlaag", "defeat"}, {"toebrengen", "inflict, deliver"} },
},

[5407] = { en = "Invader's Scourgestones", tier = 4,
  t = "Invader's Scourgestones",
  p = "Een Invader's Scourgestone is het insigne van de elitetroepen van de Scourge. Je vindt ze soms bij de sterkere troepen in de Plaguelands. Zo'n wezen doden is echt een uitdaging, maar wel een waar je van moet genieten als je een aanstelling hebt om het kwaad te verslaan.$B$BDe Argent Dawn biedt op dit moment een erepenning in ruil voor tien van deze insignes. Breng ze hier naar mij, dan zorg ik dat je je verdiende beloning krijgt.",
  c = "Gefeliciteerd, $N - ik ben blij je een erepenning van de Argent Dawn te geven!$B$BElke erepenning die aan waardige ontvangers wordt gegeven, is een teken dat het tij tegen de Scourge keert. Nu steeds meer helden de Scourge in hun eigen land bestrijden, zal de Argent Dawn zeker vooraan staan wanneer het tijd is om oorlog te voeren tegen het ultieme kwaad van de Scourge. Ik hoop dat de moed die je hebt getoond om je penning te verdienen, dan ook de doorslag zal geven!",
  g = { {"elitetroepen", "elite troops"}, {"uitdaging", "challenge"}, {"aanstelling", "commission"}, {"erepenning", "valor token"}, {"verdiende", "just, deserved (verdiend)"}, {"waardige", "worthy (waardig)"}, {"ontvangers", "recipients (ontvanger)"}, {"het tij keert", "the tide turns"}, {"bestrijden", "fight, combat"}, {"vooraan staan", "be at the forefront"}, {"ultieme", "ultimate (ultiem)"}, {"getoond", "shown (tonen)"}, {"de doorslag geven", "carry the day, be decisive"} },
},

[5408] = { en = "Minion's Scourgestones", tier = 4,
  t = "Minion's Scourgestones",
  p = "Een Minion's Scourgestone is het insigne van het gewone voetvolk van de Scourge. Je vindt ze soms bij de zwakkere troepen in de Plaguelands, al moet je het woord \"zwakker\" wel in verband zien. De Scourge, waar ze ook zijn, mag je nooit onderschatten.$B$BDe Argent Dawn biedt op dit moment een erepenning in ruil voor twintig van deze insignes - een ruil die ik graag doe, als je genoeg scourgestones hebt verdiend!",
  c = "Gefeliciteerd, $N - ik ben blij je een erepenning van de Argent Dawn te geven!$B$BDe penningen hebben twee doelen. Eén: je kunt ze gebruiken om je aanzien bij de Argent Dawn te verhogen; dat kan je opties en beloningen opleveren die bewaard worden voor onze geëerde en vereerde bondgenoten. Twee: je kunt ze, samen met geld, aan onze kwartiermeesters geven als betaling voor een aantal van de kostbaarste spullen van de Dawn.$B$BWat je ook kiest, weet dat je je aanstelling verdient. Goed gedaan!",
  g = { {"voetvolk", "rank and file, foot soldiers"}, {"in verband zien", "see in context"}, {"onderschatten", "underestimate"}, {"ruil", "exchange"}, {"penningen", "tokens (penning)"}, {"aanzien", "standing, reputation"}, {"verhogen", "raise, further"}, {"opleveren", "yield, bring"}, {"geëerde", "honored (geëerd)"}, {"vereerde", "revered (vereerd)"}, {"bondgenoten", "allies (bondgenoot)"}, {"kwartiermeesters", "quartermasters (kwartiermeester)"}, {"kostbaarste", "most prized (kostbaar)"} },
},

[5903] = { en = "A Plague Upon Thee", tier = 4,
  t = "Een plaag over jullie",
  d = "Ik heb vaak geprobeerd de Scarlet Crusade met alleen geweld te verdrijven, maar zonder succes. Daarom heb ik besloten om, als alternatief, hun leven moeilijker te maken.$B$BAls je wilt helpen, wil ik die houtzagerij besmetten met de vreselijkste soort termieten die ooit gevonden is.$B$BIn Plaguewood, vlak bij het ooit zo grootse Stratholme, leeft een soort die de plaag en de Scourge samen heeft overleefd. Zoek hun heuvels en vul deze pot ermee, zodat we ze kunnen voorbereiden om ze op de Crusade los te laten.",
  o = "Gebruik de Empty Termite Jar bij de Termite Mounds in Eastern Plaguelands. Als je 100 Plagueland Termites hebt verzameld, keer dan terug naar Nathaniel Dumah in Chillwind Camp in Western Plaguelands.",
  p = "Heb je de termietenheuvels gevonden, $N? Ik heb gehoord dat ze overal in Plaguewood zijn.",
  c = "Deze zijn prima, $N. Dank je. Kijk ze nou... zoveel, allemaal dicht op elkaar. Ik heb bijna medelijden met de Crusade, maar ja, het was ook nooit hun zagerij om in te pikken, toch?",
  g = { {"geweld", "force, violence"}, {"verdrijven", "drive out, rout"}, {"houtzagerij", "lumber mill"}, {"besmetten", "infest, infect"}, {"termieten", "termites (termiet)"}, {"grootse", "great, grand (groots)"}, {"overleefd", "survived (overleven)"}, {"heuvels", "mounds (heuvel)"}, {"los te laten", "to unleash (loslaten)"}, {"termietenheuvels", "termite mounds"}, {"medelijden", "pity"}, {"zagerij", "mill, sawmill"}, {"in te pikken", "to grab, take (inpikken)"} },
},

[5904] = { en = "A Plague Upon Thee", tier = 4,
  t = "Een plaag over jullie",
  d = "Nu we de termieten hebben, breng je dit met staal versterkte vat naar de Northridge Lumber Mill ten zuiden van Hearthglen; je vindt die ten westen van de weg die omhoog naar het stadje leidt.$B$BZet het vat daar in het midden van de houtzagerij neer; zoek een geschikte plek, bijvoorbeeld op een krat, en maak het dan open. De termieten doen daarna hun werk en maken de zagerij onbruikbaar voor de Crusade.",
  o = "Zoek een geschikte plek in het midden van de Northridge Lumber Mill in Western Plaguelands om de Barrel of Plagueland Termites neer te zetten.",
  c = "De termieten worden duidelijk onrustig als je het vat boven op de krat zet.",
  g = { {"termieten", "termites (termiet)"}, {"versterkte", "reinforced (versterkt)"}, {"vat", "barrel"}, {"stadje", "small town"}, {"houtzagerij", "lumber mill"}, {"geschikte", "suitable (geschikt)"}, {"krat", "crate"}, {"onbruikbaar", "useless, unusable"}, {"onrustig", "restless"} },
},

})

